            },
            "aggregateRules": {
              "$ref": "#/definitions/singleFieldAggregate"
            }
          }
        },
        {
          "properties": {
            "aggregateId": {
              "enum": [
                "COUNT"
              ]
            }
          }
        },
        {
          "properties": {
            "aggregateId": {
              "enum": [
                "FIRST_SEEN"
              ]
            }
          }
        },
        {
          "properties": {
            "aggregateId": {
              "enum": [
                "FIRST_VALUE"
              ]
            },
            "aggregateRules": {
              "$ref": "#/definitions/singleFieldAggregate"
            }
          }
        },
        {
          "properties": {
            "aggregateId": {
              "enum": [
                "LAST_VALUE"
              ]
            },
            "aggregateRules": {
              "$ref": "#/definitions/singleFieldAggregate"
            }
          }
        },
        {
          "properties": {
